function animate(env,el,p) {
    let t = env.time;
    var zd = p.zdist;
    var dx = p.xmag/10;
    var dy = p.ymag/10;
    var dt = p.tmag/10;
    var dz = p.zmag/50;
    var dzz;
    let mx;
    let my;
    let mz;
    let mt;

    let absTimeSeconds = env.frame/env.fps;
    let evolution = (absTimeSeconds * 1.0) - 1.0;

    //m = Math.sin(t * env.duration * p.freq * 3.14159);

    if (p.xtype == 0) {
    mx = Math.cos(t * env.duration * p.freq * (p.xfreq/10) * 3.14159 + p.xoffset);
    } else if (p.xtype == 1) {
    mx = Math.sin(t * env.duration * p.freq * (p.xfreq/10) * 3.14159 + p.xoffset);
    } else if (p.xtype == 2) {
    mx = AM.triangle(t * env.duration * p.freq * (p.xfreq/10) / 2.0 + p.xoffset);
    } else {
    mx = AM.simplexNoise(el.transform.location.x * (p.freq * (p.xfreq/10)), el.transform.location.y * (p.freq * (p.xfreq/10)), evolution + 49235.319798 + p.xoffset);
    };

    if (p.ytype == 0) {
    my = Math.cos(t * env.duration * p.freq * (p.yfreq/10) * 3.14159 + p.yoffset);
    } else if (p.ytype == 1) {
    my = Math.sin(t * env.duration * p.freq * (p.yfreq/10) * 3.14159 + p.yoffset);
    } else if (p.ytype == 2) {
    my = AM.triangle(t * env.duration * p.freq * (p.yfreq/10) / 2.0 + p.yoffset);
    } else {
    my = AM.simplexNoise(el.transform.location.x * (p.freq * (p.yfreq/10)), el.transform.location.y * (p.freq * (p.yfreq/10)), evolution + 17337.940385 + p.yoffset);
    };

    if (p.ztype == 0) {
    mz = Math.cos(t * env.duration * p.freq * (p.zfreq/10) * 3.14159 + p.zoffset);
    } else if (p.ztype == 1) {
    mz = Math.sin(t * env.duration * p.freq * (p.zfreq/10) * 3.14159 + p.zoffset);
    } else if (p.ztype == 2) {
    mz = AM.triangle(t * env.duration * p.freq * (p.zfreq/10) / 2.0 + p.zoffset);
    } else {
    mz = AM.simplexNoise(el.transform.location.x * (p.freq * (p.zfreq/10)), el.transform.location.y * (p.freq * (p.zfreq/10)), evolution + 21576.940385 + p.zoffset);
    };

    if (p.ttype == 0) {
    mt = Math.cos(t * env.duration * p.freq * (p.tfreq/10) * 3.14159 + p.toffset);
    } else if (p.ttype == 1) {
    mt = Math.sin(t * env.duration * p.freq * (p.tfreq/10) * 3.14159 + p.toffset);
    } else if (p.ttype == 2) {
    mt = AM.triangle(t * env.duration * p.freq * (p.tfreq/10) / 2.0 + p.toffset);
    } else {
    mt = AM.simplexNoise(el.transform.location.x * (p.freq * (p.tfreq/10)), el.transform.location.y * (p.freq * (p.tfreq/10)), evolution + 35321.940385 + p.toffset);
    };

    dx *= dx * mx * p.mag;
    dy *= dy * my * p.mag;
    dt *= dt * mt * p.mag;
    dz *= dz * mz * p.mag;
    dzz = zd + dz - 1;
    el.transform.location.x += dx;
    el.transform.location.y += dy;
    el.transform.angle += p.rot + dt;
    el.transform.scale.x += dzz;
    el.transform.scale.y += dzz;
    return el;
}
